  r=new Rig();r.begin();r.phone();r.f.permission=false;r.until(M6Controller.State.PERMISSION_PENDING);r.c.permissionCallback("WRONG_NONCE",r.c.target(),true);check(r.c.state()==M6Controller.State.PERMISSION_PENDING,"Wrong callback ignored");r.c.permissionCallback(r.nonce,normal(0x2765,2),true);check(r.c.state()==M6Controller.State.PERMISSION_PENDING,"Wrong device ignored");r.f.permission=true;r.c.permissionCallback(r.nonce,r.c.target(),true);r.c.permissionCallback(r.nonce,r.c.target(),true);r.until(M6Controller.State.WAIT_DETACH);r.f.devices=new UsbIdentity[]{accessory(0x2d01,2)};r.c.step();scenario("04-own-permission-grant",r,M6Controller.Verdict.PASS);check(r.f.requests==1&&r.c.callbackCount()==1,"Exactly one request and callback");
