  r=new Rig();r.begin();r.phone();r.until(M6Controller.State.WAIT_DETACH);r.f.devices=new UsbIdentity[0];r.c.step();r.c.step();r.f.time+=15000;r.c.step();scenario("09-detach-no-accessory",r,M6Controller.Verdict.INCONCLUSIVE);
  r=new Rig();r.begin();r.f.devices=new UsbIdentity[]{accessory(0x2d01,2)};r.c.step();scenario("10-already-accessory",r,M6Controller.Verdict.INCONCLUSIVE);check(r.f.calls==0,"No accessory open/transfer");
  r=new Rig();r.begin();r.phone();r.until(M6Controller.State.IDENTITY_PENDING);r.f.devices=new UsbIdentity[]{accessory(0x2d05,2)};r.c.step();scenario("11-honda-switched-first",r,M6Controller.Verdict.INCONCLUSIVE);check(r.f.startCalls==0,"No START on accessory");
  for(int pid:new int[]{0x2d00,0x2d01,0x2d04,0x2d05}){r=new Rig();r.begin();r.phone();r.until(M6Controller.State.WAIT_DETACH);r.f.devices=new UsbIdentity[]{accessory(pid,2)};r.c.step();scenario("12-accessory-"+pid,r,M6Controller.Verdict.PASS);}
  for(int pid:new int[]{0x2d02,0x2d03,0x2d06}){r=new Rig();r.begin();r.phone();r.until(M6Controller.State.WAIT_DETACH);r.f.devices=new UsbIdentity[0];r.c.step();r.f.devices=new UsbIdentity[]{accessory(pid,2)};r.c.step();scenario("13-nondata-accessory-"+pid,r,M6Controller.Verdict.INCONCLUSIVE);}
  r=new Rig();r.begin();r.phone();r.until(M6Controller.State.WAIT_DETACH);r.f.devices=new UsbIdentity[0];r.c.step();r.f.devices=new UsbIdentity[]{normal(0x2765,2)};r.c.step();scenario("14-normal-reappeared",r,M6Controller.Verdict.INCONCLUSIVE);
  r=new Rig();r.begin();r.f.devices=new UsbIdentity[]{normal(0x2769,1),normal(0x2765,2)};r.c.step();scenario("15-multiple-targets",r,M6Controller.Verdict.INCONCLUSIVE);
