  r=new Rig();r.begin();r.phone();r.until(M6Controller.State.WAIT_DETACH);r.f.time+=10001;r.f.devices=new UsbIdentity[]{accessory(0x2d01,2)};r.c.step();scenario("27-late-detach",r,M6Controller.Verdict.INCONCLUSIVE);
  r=new Rig();r.begin();r.phone();r.until(M6Controller.State.WAIT_DETACH);r.f.devices=new UsbIdentity[0];r.c.step();r.f.time+=15001;r.f.devices=new UsbIdentity[]{accessory(0x2d01,2)};r.c.step();scenario("28-late-accessory",r,M6Controller.Verdict.INCONCLUSIVE);
